def wrap_single_quotes(s):
    parts = ["'"]
    for ch in s:
        if ch == "'":
            parts.append("\\'")
        else:
            parts.append(ch)
    parts.append("'")
    return ''.join(parts)

def trailing_zeros_factorial(n):
    if n < 5:
        return 0
    quotient = n // 5
    return quotient + trailing_zeros_factorial(quotient)

