def format_row(cells, widths):
    parts = []
    for cell, width in zip(cells, widths):
        parts.append('{:<{w}}'.format(cell, w=width))
    return ' '.join(parts)

def unflatten_dict(flat, sep):
    def insert(node, parts, value):
        if len(parts) == 1:
            node[parts[0]] = value
            return
        head, rest = parts[0], parts[1:]
        if head not in node or not isinstance(node[head], dict):
            node[head] = {}
        insert(node[head], rest, value)

    root = {}
    for key, value in flat.items():
        insert(root, key.split(sep), value)
    return root

