def partition_even_odd_values(lst):
    is_even = lambda x: x % 2 == 0
    evens = list(filter(is_even, lst))
    odds = list(filter(lambda x: not is_even(x), lst))
    return (evens, odds)

def mode_progression(items):
    counts = {}
    best_item = None
    best_count = 0
    result = []
    for x in items:
        counts[x] = counts.get(x, 0) + 1
        if counts[x] > best_count or (counts[x] == best_count and x < best_item):
            best_item = x
            best_count = counts[x]
        result.append(best_item)
    return result

