        tally[key] = tally.get(key, 0) + 1
    return len(tally)

def rank_percentile_bucket(scores):
    thresholds = [(75, 'Q4'), (50, 'Q3'), (25, 'Q2'), (0, 'Q1')]
    result = []
    for s in scores:
        for cutoff, label in thresholds:
            if s >= cutoff:
                result.append(label)
                break
    return result

def is_valid_spaced_credit_card(s):
    import re
    if not re.fullmatch(r'\d{4} \d{4} \d{4} \d{4}', s):
        return False
    digits = [int(c) for c in s.replace(' ', '')]
    total = 0
    for idx, d in enumerate(reversed(digits)):
        if idx % 2 == 1:
            d = d * 2 - 9 if d * 2 > 9 else d * 2
        total += d
    return total % 10 == 0

